import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    water_count = 0
    bucket_uses = 0

    for row in grid:
        for cell in row:
            if cell == 1:
                water_count += 1
                if water_count >= capacity:
                    bucket_uses += math.ceil(water_count / capacity)
                    water_count = 0

    return bucket_uses
