import math

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less than 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if a < 2:
        return False
    factors = []
    for i in range(2, int(math.sqrt(a)) + 1):
        if a % i == 0 and is_prime(i):
            factors.append(i)
            while a % i == 0:
                a //= i
    if a > 1 and is_prime(a):
        factors.append(a)
    return len(factors) == 3
